INSERT INTO demo_reference_profiles(profile_id,name,description,span_seconds,og,source_kind,source_note,created_at) VALUES('tilt-pro-blue-20260925','Tilt Pro Blue · referanse 2026-09-25','Reell SG- og temperaturserie aggregert til 5-minutters referansepunkter. Absolutte kildetidspunkt er fjernet; relative tidsforskjeller og datagap er bevart.',253200,1.04630,'home_assistant_history','Kilde: Tilt Pro Blue SG og temperatur eksportert fra Home Assistant 2026-09-28. Råfil inngår ikke i release.',UTC_TIMESTAMP(3));
